-- ═══════════════════════════════════════════════════════════════
-- Миграция 0029: нормализация и индексы для нечёткого поиска
-- ═══════════════════════════════════════════════════════════════
--
-- Поиск по ФИО и адресам работал плохо по трём измеримым причинам.
--
-- 1. ИНДЕКС НЕ ИСПОЛЬЗОВАЛСЯ. Запрос был написан в функциональной форме
--    `word_similarity(t, p.fio) > 0.38`. GIN-индекс pg_trgm умеет ускорять
--    только ОПЕРАТОРЫ (`%`, `<%`, `%>`), а не вызовы функций, поэтому каждый
--    поиск шёл Seq Scan по 35 483 пациентам — замерено 476 мс.
--
-- 2. ТРЕБОВАЛОСЬ СОВПАДЕНИЕ ВСЕХ ТОКЕНОВ (`bool_and(... > 0.38)`). Опечатка в
--    одном слове или лишнее отчество обнуляли выдачу целиком — при том что
--    владелец просил «находиться должно всё».
--
-- 3. НЕ БЫЛО НОРМАЛИЗАЦИИ. «Фёдоров» и «Федоров» дают РАЗНЫЕ триграммы, то
--    есть по букве «ё» поиск просто не работал. То же с регистром, дефисами в
--    двойных фамилиях и типами улиц («ул.» / «улица»).
--
-- Здесь вводится нормализация и индексы под неё. Логика ранжирования — в
-- server/api/op/smart-search.post.ts.
-- ═══════════════════════════════════════════════════════════════

CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- ── Нормализация текста для поиска ──────────────────────────────
--
-- ё→е — обязательно: в базе встречаются оба написания одной фамилии, и
-- триграммы у них не пересекаются на месте буквы.
--
-- Дефис → пробел: двойная фамилия «Римский-Корсаков» должна находиться и по
-- «корсаков», а как единый токен она не найдётся.
--
-- «й» НЕ сводим к «и»: это разные буквы в фамилиях (Раскольников/Раскольнйков
-- — опечатка, а вот Гай/Гаи — разные фамилии). Опечатки такого рода закрывает
-- триграммное сходство, а не нормализация.
CREATE OR REPLACE FUNCTION search_norm(t text) RETURNS text
LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
    SELECT regexp_replace(
             regexp_replace(
               translate(lower(COALESCE(t, '')), 'ё-–—', 'е   '),
               '[^a-zа-я0-9 ]', ' ', 'g'),
             '\s+', ' ', 'g')
$$;

-- ── Ключ улицы: без типа и без порядка слов ─────────────────────
--
-- В базе встречаются и «Саляма Адиля улица», и «улица Саляма Адиля», и
-- «Саляма Адиля ул». Тип улицы отбрасывается, оставшиеся слова сортируются —
-- тогда все три написания дают один ключ.
--
-- Тот же приём уже используется в рантайме сопоставления организаций
-- (server/domain/orgMatcher.ts, normalizeStreetKey). Списки токенов обязаны
-- совпадать: если правите здесь — правьте и там.
CREATE OR REPLACE FUNCTION street_key(t text) RETURNS text
LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
    SELECT COALESCE(
        (SELECT string_agg(w, ' ' ORDER BY w)
         FROM unnest(string_to_array(search_norm(t), ' ')) AS w
         WHERE w <> ''
           AND w NOT IN ('ул','улица','ш','шоссе','пр','прт','пркт','проспект',
                         'пер','переулок','пл','площадь','б','бр','бульвар',
                         'наб','набережная','прд','проезд','туп','тупик',
                         'аллея','линия','кв','квартал','мкр','микрорайон')),
        '')
$$;

-- ── Индексы под нормализованные значения ────────────────────────
-- Именно они превращают Seq Scan в обращение по индексу. Триграммный GIN
-- работает и для `%` (similarity), и для `<%`/`%>` (word_similarity).
--
-- CONCURRENTLY обязательно: обычный CREATE INDEX берёт ShareLock и блокирует
-- ЗАПИСЬ в таблицу на время построения. Таблицы небольшие (35 тыс. пациентов),
-- построение занимает доли секунды, но система принимает вызовы круглосуточно,
-- и блокировать регистрацию новой карты нельзя даже на секунду.
--
-- Побочные условия CONCURRENTLY, которые надо знать:
--   * нельзя выполнять внутри транзакции — файл накатывать БЕЗ BEGIN/COMMIT;
--   * при сбое остаётся INVALID-индекс, его надо удалить и повторить:
--       SELECT indexrelid::regclass FROM pg_index WHERE NOT indisvalid;
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_patients_fio_norm_trgm
    ON patients USING gin (search_norm(fio) gin_trgm_ops);

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_addresses_street_norm_trgm
    ON addresses USING gin (search_norm(street) gin_trgm_ops);

CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_addresses_street_key_trgm
    ON addresses USING gin (street_key(street) gin_trgm_ops);

-- Номер дома числом: «10к1», «10с4кссК», «10 к 1» — один дом 10.
-- house_num() введена миграцией 0026.
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_addresses_house_num
    ON addresses (house_num(house));

ANALYZE patients;
ANALYZE addresses;

-- Контроль: нормализация действительно склеивает написания
SELECT search_norm('Фёдорова Анна-Мария')      AS фио_норм,
       street_key('улица Саляма Адиля')        AS ключ_1,
       street_key('Саляма Адиля ул.')          AS ключ_2,
       house_num('10с4кссК')                   AS дом;
